const sectionTitle=(number,label,action='')=>`<div class="sectionhead"><div class="row"><span class="section-no">${number}</span><h2>${esc(label)}</h2></div>${action}</div>`;
const field=(label,path,value,extra='',type='text')=>`<label class="field"><span class="label">${esc(label)}</span><input data-field="${esc(path)}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(label,path,value,values)=>`<label class="field"><span class="label">${esc(label)}</span><select data-field="${path}">${values.map(([v,k])=>option(v,t(k),value)).join('')}</select></label>`;
const caption=(text,body,id)=>`<details class="disclosure" data-open-key="${id}"><summary><span>${esc(text)}</span><small>${esc(body)}</small>${icon('chevron')}</summary>`;
let draft=null,baseline='',currentId='',mode='detail',modalOnClose=null,lastHash='',toastTimer;
let storedOpen=[];try{storedOpen=JSON.parse(localStorage.getItem(STORAGE_KEY+'.open')||'[]');}catch{}
const openDetails=new Set(Array.isArray(storedOpen)?storedOpen:[]);
const dirty=()=>draft&&JSON.stringify(draft)!==baseline;
function store(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageOK=true;return true;}catch{storageOK=false;return false;}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function modal(title,body,onClose=null){const d=$('#dialog');if(d.open)d.close();d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2>${iconBtn('x',t('close'),'data-close')}</div>${body}`;modalOnClose=onClose;d.showModal();d.querySelector('[data-close]').onclick=()=>d.close();}
$('#dialog').addEventListener('close',()=>{const fn=modalOnClose;modalOnClose=null;fn?.();});
function confirmAction(title,text,action,label=t('continue'),danger=false){modal(title,`<p class="dialog-tip">${esc(text)}</p><div class="dialog-actions">${btn(esc(t('cancel')),'id="confirm-no"')}${btn(esc(label),'id="confirm-yes"',danger?'danger':'primary')}</div>`);$('#confirm-no').onclick=()=>$('#dialog').close();$('#confirm-yes').onclick=()=>{$('#dialog').close();action();};}
function rememberOpen(){for(const el of $$('[data-open-key]'))el.open?openDetails.add(el.dataset.openKey):openDetails.delete(el.dataset.openKey);}
function restoreOpen(){for(const el of $$('[data-open-key]'))el.open=openDetails.has(el.dataset.openKey);}
function rerender(){rememberOpen();const y=window.scrollY;render();window.scrollTo(0,y);}
function requestLeave(action){
 if(!dirty()){action();return;}
 modal(t('discardTitle'),`<p class="dialog-tip">${esc(t('discardHint'))}</p><div class="dialog-actions leave-actions">${btn(esc(t('continue')),'id="leave-stay"')}${btn(esc(t('discardMove')),'id="leave-discard"','ghost')}${btn(esc(t('saveMove')),'id="leave-save"','primary')}</div>`);
 $('#leave-stay').onclick=()=>$('#dialog').close();
 $('#leave-discard').onclick=()=>{$('#dialog').close();draft=null;action();};
 $('#leave-save').onclick=()=>{$('#dialog').close();saveDraft(action);};
}
function go(hash,force=false){
 if(location.hash===hash&&!force)return;
 const move=()=>{draft=null;if(location.hash===hash)route();else location.hash=hash;};
 if(force)move();else requestLeave(move);
}
function route(){
 const match=/^#\/(work|edit)\/([^/]+)$/.exec(location.hash),nextId=match?.[2]||state.works[0]?.id,nextMode=match?.[1]==='edit'?'edit':'detail';
 if(dirty()&&location.hash!==lastHash){const next=location.hash;history.replaceState(null,'',lastHash);requestLeave(()=>go(next,true));return;}
 currentId=nextId;mode=nextMode;lastHash=`#/${mode==='edit'?'edit':'work'}/${currentId||''}`;
 if(location.hash!==lastHash)history.replaceState(null,'',lastHash);
 if(mode==='edit'&&!draft){const work=state.works.find(w=>w.id===currentId);draft=work?clone(work):blankWork();draft.id=currentId||draft.id;baseline=JSON.stringify(draft);}
 render();window.scrollTo(0,0);
}
function shell(body){
 document.body.classList.toggle('editing',mode==='edit');
 const work=draft||state.works.find(w=>w.id===currentId);
 $('#app').innerHTML=`<aside class="sidebar"><div class="brand"><span class="brandmark">f</span>Folio</div><div class="navcaption">${esc(t('personalLibrary'))}</div><button class="navitem active" data-library>${icon('book')}<span>${esc(t('library'))}</span><span class="preview-chip">PREVIEW</span></button><div class="navcaption">${esc(t('samples'))}</div>${state.works.map(w=>`<a href="#/work/${w.id}" class="navitem ${w.id===currentId?'active':''}">${icon('book')}<span>${esc(w.title)}</span></a>`).join('')}<button class="navitem" data-new>${icon('plus')}<span>${esc(t('new'))}</span></button><div class="sidebottom"><div><span class="dot"></span>${esc(t('local'))}</div><button class="secondary-action" data-policy>${esc(t('policy'))}</button><br><button class="secondary-action" data-reset>${esc(t('reset'))}</button></div></aside><main class="main"><div class="preview-strip"><div class="mobile-brand"><span class="brandmark">f</span>Folio</div><div class="strip-note"><b>${esc(t('prototype'))}</b>${esc(t('isolated'))}</div><div class="lang"><button data-lang="ja" aria-pressed="${language==='ja'}">日本語</button><button data-lang="en" aria-pressed="${language==='en'}">EN</button></div></div>${!storageOK?`<p class="storage-warning">${esc(t('storageNotice'))}</p>`:''}<div class="pagebar"><div class="breadcrumb"><button type="button" data-library>${esc(t('library'))}</button>${icon('chevron')}<span>${esc(mode==='edit'?t('edit'):work?.title||t('detail'))}</span></div><nav class="viewtabs" aria-label="${esc(t('detail'))}"><a href="#/work/${currentId}" class="${mode==='detail'?'active':''}">${esc(t('detail'))}</a><a href="#/edit/${currentId}" class="${mode==='edit'?'active':''}">${esc(t('edit'))}</a></nav></div><label class="mobile-samples"><span class="label">${esc(t('chooseSample'))}</span><select id="sample-select">${state.works.map(w=>option(w.id,w.title,currentId)).join('')}</select></label>${body}<footer class="footer"><span>FOLIO / WORKSPACE PREVIEW · 01</span><span>${esc(t('copyright'))}</span><div class="mobile-tools"><button class="secondary-action" data-policy>${esc(t('policy'))}</button><button class="secondary-action" data-reset>${esc(t('reset'))}</button></div></footer></main>`;
 $$('[data-lang]').forEach(b=>b.onclick=()=>{language=b.dataset.lang;try{localStorage.setItem(STORAGE_KEY+'.language',language);}catch{}rerender();});
 $$('[data-reset]').forEach(b=>b.onclick=()=>confirmAction(t('confirmReset'),t('resetHint'),()=>{state=fixtures();draft=null;store();go('#/work/atelier',true);},t('reset'),true));
 $$('[data-policy]').forEach(b=>b.onclick=prioritiesDialog);
 $$('[data-library]').forEach(b=>b.onclick=libraryDialog);
 $$('[data-new]').forEach(b=>b.onclick=()=>requestLeave(newWork));
 $('#sample-select').onchange=e=>go('#/work/'+e.target.value);
 document.documentElement.lang=language;document.title=`${work?.title||t('new')} ${mode==='edit'?'· '+t('edit'):''} - Folio Preview`;
 // Guard hash navigation synchronously so the unsaved form remains intact.
 $$('a[href^="#/"]').forEach(a=>a.onclick=e=>{e.preventDefault();go(a.getAttribute('href'));});
}
function cover(work,link=false){const src=work.cover==='./cover.svg'||safeURL(work.cover)?work.cover:'';const content=src?`<img src="${esc(src)}" alt="${esc(work.title||t('mockCover'))}" referrerpolicy="no-referrer">`:`<div class="empty-cover">${esc(t('noCover'))}</div>`;const primary=work.links.find(l=>l.primary)||work.links[0];return link&&primary&&safeURL(primary.url)?`<a class="cover-box" href="${esc(primary.url)}" target="_blank" rel="noopener noreferrer" title="${esc(t('openSource'))}">${content}</a>`:`<div class="cover-box">${content}</div>`;}
function imageErrors(){for(const img of $$('img'))img.onerror=()=>{const box=document.createElement('div');box.className='empty-cover';box.textContent=t('coverFailed');img.replaceWith(box);};}
function summary(work){const pages=representativePages(work,state.priorities),date=representativeDate(work,state.priorities);return {pages,date,languages:allLanguages(work)};}
function stars(value,max=5,symbol='★'){return `<span class="stars">${esc(symbol.repeat(value||0))}<span class="off">${esc((symbol==='♥'?'♡':'☆').repeat(max-(value||0)))}</span></span>`;}
const markDefs=[['○','購入済み','Owned'],['△','読みたい','To read'],['□','読了','Read'],['♡','お気に入り','Favorite'],['◇','再読したい','Read again']];
function markButtons(work){return `<div class="marks">${markDefs.map(([symbol,ja,en],i)=>`<button type="button" class="mark" data-mark="${i+1}" aria-pressed="${work.marks.includes(i+1)}"><span>${symbol}</span><small>${esc(language==='ja'?ja:en)}</small></button>`).join('')}</div>`;}
function metadata(work,k){const values=k==='characters'?work.characters.map(id=>state.characters.find(c=>c.id===id)?.name).filter(Boolean):work[k];return values.length?`<section class="meta-section"><h3>${esc(t(k))}</h3><div class="tags">${values.map(v=>tag(v.name||v,v.gender||'none',`data-meta="${k}" data-name="${esc(v.name||v)}"`)).join('')}</div></section>`:'';}
function detailPage(work){
 const s=summary(work),primary=work.links.find(l=>l.primary)||work.links[0],charsSummary=[...work.originals,...work.characters.map(id=>state.characters.find(c=>c.id===id)?.name)].filter(Boolean).join(' · ');
 const identity=work.creation==='derivative'?metadata(work,'originals')+metadata(work,'characters'):'';
 shell(`<div class="detail-grid"><aside class="cover-column">${cover(work,true)}<div class="cover-caption"><span>${esc(t('mockCover'))}</span>${icon('external')}</div>${primary?`<a class="btn primary" href="${esc(safeURL(primary.url)?primary.url:'#')}" target="_blank" rel="noopener noreferrer">${icon('external')}${esc(t('openSource'))}</a>`:''}<p class="cover-note">${esc(t('demoLinks'))}</p></aside><article><div class="detail-intro"><div class="row between"><div class="badge-line">${[work.format,work.publication,work.creation].filter(Boolean).map(v=>pill(t(v))).join('')}</div><div class="row detail-actions">${iconBtn('share',t('share'),'id="share"')}${iconBtn('trash',t('delete'),'id="delete"','danger')}${iconBtn('edit',t('edit'),'id="edit"')}</div></div><h1 class="detail-title">${esc(work.title)}</h1><div class="authorline">${work.authors.map(a=>`<button class="linkbutton" data-meta="authors" data-name="${esc(a)}">${esc(a)}</button>`).join(' / ')}${work.circles.length?`<span class="muted">/</span>${work.circles.map(c=>`<button class="linkbutton" data-meta="circles" data-name="${esc(c)}">${esc(c)}</button>`).join(' / ')}`:''}</div><div class="fact-row"><div class="fact"><small>${esc(t('languages'))}</small><b>${esc(s.languages.join(' / ')||'—')}</b></div><div class="fact"><small>${esc(t('pages'))}</small><button type="button" data-summary><b>${s.pages?.pages??'—'}</b> <small>ⓘ</small></button></div><div class="fact"><small>${esc(s.date?t(s.date.date.kind):t('date'))}</small><button type="button" data-summary><b>${esc(s.date?.date.value||'—')}</b> <small>ⓘ</small></button></div></div></div><section class="personal"><div class="row between"><span class="eyebrow">${esc(t('personal'))}</span><details class="mark-menu" data-open-key="detail-marks"><summary><span>${esc(t('marks'))}</span><span class="mark-symbols">${work.marks.map(n=>markDefs[n-1][0]).join('')||'＋'}</span></summary>${markButtons(work)}</details></div><div class="overall"><span class="muted">${esc(t('overall'))}</span>${stars(work.ratings.overall)}${work.ratings.overall?`<strong>${work.ratings.overall}<small> / 5</small></strong>`:`<small>${esc(t('unrated'))}</small>`}</div>${state.dimensions.filter(d=>d.number!==0).map(d=>`<div class="custom-rating"><span>${d.number}. ${esc(d.name)}</span>${stars(work.ratings[d.id],d.maximum,d.symbol)}<small>${work.ratings[d.id]?work.ratings[d.id]+'/'+d.maximum:t('unrated')}</small></div>`).join('')}</section>${metadata(work,'tags')}${identity}${metadata(work,'series')}${work.review?`<section class="meta-section"><h3>${esc(t('review'))}</h3><p class="review">${esc(work.review)}</p></section>`:''}<section class="source-section">${sectionTitle('01',t('source'),`<small>${work.links.length}</small>`)}${work.links.map((l,i)=>sourceCard(l,i)).join('')||`<p class="empty">—</p>`}</section><div class="detail-extras">${caption(t('extra'),[t(work.age),t(work.ai==='unknown'?'unknown':work.ai),...(work.creation!=='derivative'?[charsSummary]:[])].filter(Boolean).join(' · '),'detail-extra')}<div class="grid"><div><span class="label">${esc(t('age'))}</span>${pill(t(work.age))}</div><div><span class="label">${esc(t('ai'))}</span>${pill(t(work.ai))}${work.aiSource?`<p class="cover-note">${esc(work.aiSource)}</p>`:''}</div></div>${work.creation!=='derivative'?metadata(work,'originals')+metadata(work,'characters'):''}<section class="meta-section"><h3>${esc(t('relations'))}</h3>${work.relations.map(r=>`<div class="relation">${r.entry&&state.works.some(w=>w.id===r.entry)?`<a href="#/work/${esc(r.entry)}">${esc(r.name||state.works.find(w=>w.id===r.entry)?.title)}</a>`:`<span>${esc(r.name)}</span>`}${r.url&&safeURL(r.url)?`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer" aria-label="${esc(t('externalURL'))}">${icon('external')}</a>`:''}${!r.entry?`<small>${esc(t('unregistered'))}</small>`:''}</div>`).join('')||`<p class="empty">${esc(t('emptyRelations'))}</p>`}</section></div></details></div></article></div>`);
 $('#edit').onclick=()=>go('#/edit/'+work.id);
 $('#share').onclick=()=>modal(t('share'),`<p class="dialog-tip">${esc(t('shareHint'))}</p>`);
 $('#delete').onclick=()=>confirmAction(t('deleteTitle'),t('deleteHint'),()=>{state.works=state.works.filter(w=>w.id!==work.id);store();go('#/work/'+(state.works[0]?.id||''),true);},t('delete'),true);
 $$('[data-summary]').forEach(b=>b.onclick=()=>summaryDialog(work));
 $$('[data-mark]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.mark);work.marks=work.marks.includes(n)?work.marks.filter(v=>v!==n):[...work.marks,n].sort();store();rerender();});
 $$('[data-source-toggle]').forEach(b=>b.onclick=()=>{
  const expanded=b.getAttribute('aria-expanded')!=='true',key=b.dataset.sourceToggle;
  b.setAttribute('aria-expanded',String(expanded));document.getElementById(b.getAttribute('aria-controls')).hidden=!expanded;
  expanded?openDetails.add(key):openDetails.delete(key);
  try{localStorage.setItem(STORAGE_KEY+'.open',JSON.stringify([...openDetails]));}catch{}
 });
 bindMetadataSearch();
}
function sourceCard(l,i){
 const key='source-'+l.id,expanded=openDetails.has(key),contentId='source-supplement-'+i;
 const mainDate=l.dates.find(d=>d.kind==='release'&&d.value)||l.dates.find(d=>d.kind==='published'&&d.value);
 const facts=[t(l.role==='other'?'unconfirmed':l.role),l.languages.join(' / '),l.pages!==null?l.pages+' '+t('pages'):'',mainDate?t(mainDate.kind)+' '+mainDate.value:''].filter(Boolean);
 return `<article class="source-card"><div class="source-row"><a class="source-main" href="${esc(safeURL(l.url)?l.url:'#')}" target="_blank" rel="noopener noreferrer"><span class="source-icon">${esc(({dlsite:'DL',fanza:'FZ',pixiv:'Px',fanbox:'FB',other:'↗'})[l.site]||'↗')}</span><span class="source-info"><strong>${esc(l.label||l.url)}</strong> ${l.primary?pill(t('primary'),true):''}<small>${esc(facts.join(' · '))}</small></span>${icon('external')}</a><button type="button" class="source-toggle" data-source-toggle="${esc(key)}" aria-expanded="${expanded}" aria-controls="${contentId}" aria-label="${esc(t('sourceToggle')+' · '+(l.label||l.url))}" title="${esc(t('sourceToggle'))}">${icon('chevron')}</button></div><div class="source-content" id="${contentId}" ${expanded?'':'hidden'}><a class="url" href="${esc(safeURL(l.url)?l.url:'#')}" target="_blank" rel="noopener noreferrer">${esc(l.url)} ${icon('external')}</a>${l.dates.filter(d=>d.value).map(d=>`<div class="date-row"><small>${esc(d.kind==='other'?d.label||t('dateOther'):t(d.kind))}</small><span>${esc(d.value)}</span></div>`).join('')}</div></article>`;
}
function summaryDialog(work){const s=summary(work);modal(t('summarySource'),`<div class="stack"><div><span class="label">${esc(t('chosenPages'))}</span><p>${esc(s.pages?(s.pages.label||s.pages.url)+' · '+s.pages.pages:t('sourceUnavailable'))}</p></div><div><span class="label">${esc(t('chosenDate'))}</span><p>${esc(s.date?(s.date.link.label||s.date.link.url)+' · '+t(s.date.date.kind)+' '+s.date.date.value:t('sourceUnavailable'))}</p></div><div><span class="label">${esc(t('languages'))}</span><p>${esc(s.languages.join(' / ')||'—')}</p><small>${esc(t('allLanguageHint'))}</small></div></div><p class="dialog-tip">${esc(t('priorityHint'))}</p><p class="dialog-tip">${esc(t('datePriorityHint'))}</p>${btn(esc(t('policy')),'id="summary-policy"')}`);$('#summary-policy').onclick=prioritiesDialog;}
function chipField(k){const values=k==='characters'?draft.characters.map(id=>({id,name:state.characters.find(c=>c.id===id)?.name||id})):draft[k];return `<div class="field"><span class="label">${esc(t(k))}</span><div class="chip-field">${values.map((v,i)=>`<span class="tag ${v.gender||''}"><button type="button" class="tag-name" data-chip-settings="${k}:${i}">${esc(v.name||v)}${v.gender==='female'?' ♀':v.gender==='male'?' ♂':''}</button><button type="button" data-remove-chip="${k}:${i}" aria-label="${esc(t('remove')+' '+(v.name||v))}">×</button></span>`).join('')}<button type="button" class="add-chip" data-picker="${k}">＋ ${esc(t('select'))}</button></div></div>`;}
function identityFields(){return `<div class="grid">${chipField('originals')}${chipField('characters')}</div><p class="hint compact">${esc(t('associationHint'))}</p>`;}
function editorPage(){
 const d=draft,identity=d.creation==='derivative'?identityFields():'';
 shell(`<div class="edit-grid"><aside class="edit-cover"><h1>${esc(t('edit'))}</h1>${cover(d)}<div class="field">${field(t('cover'),'cover',d.cover,'placeholder="https://…"')}<small>${esc(t('coverHint'))}</small><button type="button" class="secondary-action" id="refresh-cover">${esc(t('detail'))} ↻</button></div></aside><form id="work-form" novalidate><div id="form-errors"></div><section class="panel">${sectionTitle('01',t('title'))}<div class="stack">${field(t('title')+' · '+t('required'),'title',d.title,'required class="title-input"')}<div class="grid">${select(t('format'),'format',d.format,[['','unspecified'],['manga','manga'],['cg','cg'],['other','other']])}${select(t('publication'),'publication',d.publication,[['','unspecified'],['doujin','doujin'],['commercial','commercial']])}${select(t('creation'),'creation',d.creation,[['','unspecified'],['original','original'],['derivative','derivative']])}</div><div class="grid">${chipField('authors')}${chipField('circles')}</div>${chipField('tags')}${identity}</div></section><section class="panel">${sectionTitle('02',t('source'),btn(icon('plus')+esc(t('addLink')),'id="add-link"','small-btn'))}<p class="dialog-tip">${esc(t('demoLinks'))}</p><div id="links">${d.links.map(linkEditor).join('')}</div></section><section class="panel">${sectionTitle('03',t('personal'))}<div>${state.dimensions.map(dim=>`<div class="score-row"><div class="score-name">${esc(dim.number===0?t('overall'):dim.name)}<small>rating${dim.number} · 1–${dim.maximum}</small></div><div class="score-buttons">${Array.from({length:dim.maximum},(_,i)=>`<button type="button" data-score="${dim.id}:${i+1}" class="${i<(d.ratings[dim.id]||0)?'on':''}" aria-label="${esc((dim.number===0?t('overall'):dim.name)+' '+(i+1)+'/'+dim.maximum)}" aria-pressed="${d.ratings[dim.id]===i+1}">${dim.symbol==='♥'?(i<(d.ratings[dim.id]||0)?'♥':'♡'):(i<(d.ratings[dim.id]||0)?'★':'☆')}</button>`).join('')}<button type="button" class="clear" data-score="${dim.id}:0">${esc(t('clear'))}</button></div></div>`).join('')}</div><div class="subsection"><span class="label">${esc(t('marks'))}</span>${markButtons(d)}</div><div class="subsection"><label class="field"><span class="label">${esc(t('review'))}</span><textarea data-field="review">${esc(d.review)}</textarea></label></div></section><section class="panel">${sectionTitle('04',t('extra'))}<div class="stack">${d.creation!=='derivative'?identityFields():''}${chipField('series')}<div class="grid">${select(t('age'),'age',d.age,[['adult','adult'],['allAges','allAges'],['unknown','unknown']])}${select(t('ai'),'ai',d.ai,[['unknown','unknown'],['generated','generated'],['partial','partial'],['nonGenerated','nonGenerated']])}</div><div><p class="dialog-tip">${esc(t('aiHint'))}</p>${field(t('aiSource'),'aiSource',d.aiSource)}</div><div><div class="row between"><h3>${esc(t('relations'))}</h3>${btn(icon('plus')+esc(t('addRelation')),'id="add-relation"','small-btn')}</div>${d.relations.map((r,i)=>`<div class="input-relation"><div class="row between"><span class="label">${esc(t('relations'))} ${i+1}</span>${iconBtn('x',t('remove'),`data-remove-relation="${i}"`)}</div><div class="stack">${field(t('relationName'),`relations.${i}.name`,r.name)}<label class="field"><span class="label">${esc(t('relationEntry'))}</span><select data-field="relations.${i}.entry">${option('',t('unregistered'),r.entry)}${state.works.filter(w=>w.id!==d.id).map(w=>option(w.id,w.title,r.entry)).join('')}</select></label>${field(t('externalURL'),`relations.${i}.url`,r.url,'placeholder="https://…"','url')}</div></div>`).join('')}</div></div></section><div class="savebar">${btn(esc(t('cancel')),'data-cancel-edit','ghost')}<button class="btn primary" type="submit">${icon('check')}${esc(t('save'))}</button></div></form></div><div class="editor-savebar" role="region" aria-label="${esc(t('edit'))}"><span>${esc(t('edit'))}<small>${esc(d.title||t('new'))}</small></span><div class="row">${btn(esc(t('cancel')),'data-cancel-edit','ghost')}<button class="btn primary" type="submit" form="work-form">${icon('check')}${esc(t('saveAction'))}</button></div></div>`);
 bindEditor();
}
function linkEditor(l,i){const prefix=`links.${i}`;return `<div class="link-form"><div class="link-form-head"><label><input type="radio" name="primary" data-primary="${i}" ${l.primary?'checked':''}>${esc(t('primary'))}</label><span class="muted">${String(i+1).padStart(2,'0')}</span>${iconBtn('x',t('remove'),`data-remove-link="${i}"`)}</div><div class="stack">${field('URL',prefix+'.url',l.url,'placeholder="https://…"','url')}${field(t('linkLabel'),prefix+'.label',l.label)}</div><div class="link-metadata"><div class="stack"><div class="grid">${select(t('role'),prefix+'.role',l.role,[['main','main'],['sample','sample'],['other','unconfirmed']])}</div><div><span class="label">${esc(t('languages'))}</span><div class="language-toggles">${unique(['日本語','English','中文','한국어','文字なし',...l.languages]).map(v=>`<button type="button" data-language="${i}" data-value="${esc(v)}" aria-pressed="${l.languages.includes(v)}">${esc(v)}</button>`).join('')}</div><div class="inline-input"><input id="language-${i}" aria-label="${esc(t('addLanguage'))}" placeholder="${esc(t('addLanguage'))}"><button class="btn" type="button" data-add-language="${i}" aria-label="${esc(t('addLanguage'))}">＋</button></div></div>${field(t('pages'),prefix+'.pages',l.pages??'','min="0" step="1"','number')}<div><span class="label">${esc(t('date'))}</span>${l.dates.map((d,j)=>`<div class="date-edit"><select data-field="${prefix}.dates.${j}.kind" aria-label="${esc(t('dateLabel'))}">${['release','published','other'].map(k=>option(k,t(k==='other'?'dateOther':k),d.kind)).join('')}</select><input data-field="${prefix}.dates.${j}.value" value="${esc(d.value)}" placeholder="YYYY-MM-DD" inputmode="numeric" aria-label="${esc(t('date'))}">${iconBtn('x',t('remove'),`data-remove-date="${i}:${j}"`)}${d.kind==='other'?`<input class="date-label" data-field="${prefix}.dates.${j}.label" value="${esc(d.label)}" placeholder="${esc(t('dateLabel'))}" aria-label="${esc(t('dateLabel'))}">`:''}</div>`).join('')}<p class="dialog-tip">${esc(t('dateHint'))}</p>${btn(icon('plus')+esc(t('addDate')),`data-add-date="${i}"`,'small-btn')}</div></div></div></div>`;}
function updateField(path,value){const parts=path.split('.');let target=draft;for(const key of parts.slice(0,-1))target=target[key];const key=parts.at(-1);if(key==='url'&&parts[0]==='links')target.site=sourceSite(value,target.site,target.url);target[key]=key==='pages'?(value===''?null:Number(value)):value;}
function bindEditor(){
 $$('[data-field]').forEach(el=>{
  el.oninput=()=>updateField(el.dataset.field,el.value);
  if(el.tagName==='SELECT')el.onchange=()=>{updateField(el.dataset.field,el.value);if(el.dataset.field.endsWith('.entry')){const i=Number(el.dataset.field.split('.')[1]),work=state.works.find(w=>w.id===el.value);if(work&&!draft.relations[i].name)draft.relations[i].name=work.title;}rerender();};
 });
 $('#refresh-cover').onclick=rerender;
 $$('[data-cancel-edit]').forEach(b=>b.onclick=()=>go('#/work/'+(state.works.some(w=>w.id===currentId)?currentId:state.works[0]?.id||'')));
 $('#work-form').onsubmit=e=>{e.preventDefault();saveDraft();};
 $$('[data-primary]').forEach(el=>el.onchange=()=>{draft.links.forEach((l,i)=>l.primary=i===Number(el.dataset.primary));rerender();});
 $('#add-link').onclick=()=>{const l={id:uid(),url:'',label:'',site:'other',role:'other',languages:[],pages:null,dates:[],primary:!draft.links.length};draft.links.push(l);openDetails.add('link-edit-'+l.id);rerender();$$('[data-field]').find(e=>e.dataset.field===`links.${draft.links.length-1}.url`)?.focus();};
 $$('[data-remove-link]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.removeLink),was=draft.links[i].primary;draft.links.splice(i,1);if(was&&draft.links.length)draft.links[0].primary=true;rerender();});
 $$('[data-language]').forEach(b=>b.onclick=()=>{const l=draft.links[Number(b.dataset.language)],v=b.dataset.value;l.languages=l.languages.includes(v)?l.languages.filter(x=>x!==v):[...l.languages,v];rerender();});
 $$('[data-add-language]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.addLanguage),input=$('#language-'+i),v=input.value.trim();if(v){draft.links[i].languages=unique([...draft.links[i].languages,v]);rerender();}});
 $$('[data-add-language]').forEach(b=>{$('#language-'+b.dataset.addLanguage).onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();b.click();}};});
 $$('[data-add-date]').forEach(b=>b.onclick=()=>{draft.links[Number(b.dataset.addDate)].dates.push({kind:'release',value:'',label:''});rerender();});
 $$('[data-remove-date]').forEach(b=>b.onclick=()=>{const [i,j]=b.dataset.removeDate.split(':').map(Number);draft.links[i].dates.splice(j,1);rerender();});
 $$('[data-picker]').forEach(b=>b.onclick=()=>picker(b.dataset.picker));
 $$('[data-remove-chip]').forEach(b=>b.onclick=()=>{const [k,i]=b.dataset.removeChip.split(':');draft[k].splice(Number(i),1);rerender();});
 $$('[data-chip-settings]').forEach(b=>b.onclick=()=>{const [k,index]=b.dataset.chipSettings.split(':'),i=Number(index);if(k==='characters')characterDialog(draft.characters[i]);else if(k==='tags')tagDialog(i);else picker(k);});
 $$('[data-score]').forEach(b=>b.onclick=()=>{const [id,v]=b.dataset.score.split(':');if(Number(v))draft.ratings[id]=Number(v);else delete draft.ratings[id];rerender();});
 $$('[data-mark]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.mark);draft.marks=draft.marks.includes(n)?draft.marks.filter(x=>x!==n):[...draft.marks,n].sort();rerender();});
 $('#add-relation').onclick=()=>{draft.relations.push({id:uid(),name:'',entry:'',url:''});openDetails.add('edit-extra');rerender();};
 $$('[data-remove-relation]').forEach(b=>b.onclick=()=>{draft.relations.splice(Number(b.dataset.removeRelation),1);rerender();});
}
function saveDraft(afterSave){
 const issues=errors(draft);
 draft.relations.forEach((r,i)=>{if(r.url&&!safeURL(r.url))issues.push({path:`relations.${i}.url`,key:'needURL'});});
 if(issues.length){$('#form-errors').innerHTML=`<div class="errorbox" role="alert"><b>${esc(t('fixErrors'))}</b><ul>${issues.map(e=>`<li>${esc(t(e.key))}</li>`).join('')}</ul></div>`;for(const issue of issues){const input=$$('[data-field]').find(el=>el.dataset.field===issue.path);if(input){input.setAttribute('aria-invalid','true');let ancestor=input.parentElement;while(ancestor){if(ancestor.tagName==='DETAILS')ancestor.open=true;ancestor=ancestor.parentElement;}}}$$('[data-field]').find(el=>el.dataset.field===issues[0].path)?.focus();return;}
 const previous=clone(state),saved=clone(draft);saved.title=saved.title.trim();saved.relations=saved.relations.filter(r=>r.name||r.entry||r.url);
 const added=associate(saved,state.characters),i=state.works.findIndex(w=>w.id===saved.id);if(i>=0)state.works[i]=saved;else state.works.push(saved);
 if(!store()){state=previous;toast(t('saveFailed'));return;}
 draft=null;if(typeof afterSave==='function')afterSave();else go('#/work/'+saved.id,true);toast(t('saved')+(added.length?' · '+added.join(', ')+' → '+saved.originals[0]:''));
}
function picker(kind){
 let gender='none';
 const selected=()=>kind==='characters'?draft.characters:kind==='tags'?draft.tags.map(v=>v.name+'|'+v.gender):draft[kind];
 function candidates(){if(kind==='characters')return state.characters.map(c=>({key:c.id,name:c.name,detail:c.originals.join(' / ')}));const vals=state.works.flatMap(w=>w[kind]||[]).concat(draft[kind]||[]);return [...new Map(vals.map(v=>[typeof v==='string'?v:v.name+'|'+v.gender,{key:typeof v==='string'?v:v.name+'|'+v.gender,name:v.name||v,gender:v.gender||'none'}])).values()];}
 modal(t(kind),`<input id="picker-query" aria-label="${esc(t('search'))}" placeholder="${esc(t('search'))}">${kind==='tags'?`<div class="gender-choice">${['none','female','male'].map(k=>btn(esc(t(k)),`data-picker-gender="${k}" aria-pressed="${k==='none'}"`)).join('')}</div>`:''}<div id="picker-list" class="dialog-list"></div><div class="dialog-actions">${btn(esc(t('create')),'id="picker-create"','primary')}</div>`,()=>rerender());
 function draw(){const q=$('#picker-query').value.trim().toLocaleLowerCase();$('#picker-list').innerHTML=candidates().filter(c=>c.name.toLocaleLowerCase().includes(q)).map(c=>`<button type="button" class="option-row" data-pick="${esc(c.key)}"><span>${esc(c.name)}${c.gender==='female'?' ♀':c.gender==='male'?' ♂':''}${c.detail?`<small>${esc(c.detail)}</small>`:''}</span>${selected().includes(kind==='characters'||kind==='tags'?c.key:c.name)?`<span class="selected">${icon('check')}</span>`:icon('plus')}</button>`).join('');$('#picker-create').disabled=!q;$$('[data-pick]').forEach(b=>b.onclick=()=>{const c=candidates().find(c=>c.key===b.dataset.pick);if(kind==='characters'){draft.characters=unique([...draft.characters,c.key]);}else if(kind==='tags'){if(!draft.tags.some(v=>v.name===c.name&&v.gender===c.gender))draft.tags.push({name:c.name,gender:c.gender});}else draft[kind]=unique([...draft[kind],c.name]);draw();});}
 $('#picker-query').oninput=draw;
 $$('[data-picker-gender]').forEach(b=>b.onclick=()=>{gender=b.dataset.pickerGender;$$('[data-picker-gender]').forEach(x=>x.setAttribute('aria-pressed',x===b));});
 const create=()=>{const name=$('#picker-query').value.trim();if(!name)return;if(kind==='characters'){const c={id:uid(),name,originals:[],blocked:[]};state.characters.push(c);draft.characters=unique([...draft.characters,c.id]);}else if(kind==='tags'){if(!draft.tags.some(v=>v.name===name&&v.gender===gender))draft.tags.push({name,gender});}else draft[kind]=unique([...draft[kind],name]);$('#dialog').close();};
 $('#picker-create').onclick=create;$('#picker-query').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();create();}};draw();$('#picker-query').focus();
}
function tagDialog(index){const current=draft.tags[index];modal(t('tags'),`<p>${esc(current.name)}</p><div class="gender-choice">${['none','female','male'].map(k=>btn(esc(t(k)),`data-set-gender="${k}" aria-pressed="${k===current.gender}"`)).join('')}</div>`);$$('[data-set-gender]').forEach(b=>b.onclick=()=>{const value={...current,gender:b.dataset.setGender};draft.tags=draft.tags.filter((v,i)=>i===index||v.name!==value.name||v.gender!==value.gender);const n=draft.tags.indexOf(current);if(n>=0)draft.tags[n]=value;$('#dialog').close();rerender();});}
function characterDialog(id){
 const c=state.characters.find(c=>c.id===id);if(!c)return;
 modal(c.name,`<p class="dialog-tip">${esc(t('associationScope'))}</p><h3>${esc(t('connected'))}</h3><div class="dialog-list">${c.originals.map(o=>`<div class="option-row"><span>${esc(o)}</span>${btn(esc(t('disconnect')),`data-disconnect="${esc(o)}"`,'small-btn')}</div>`).join('')||`<p class="empty">—</p>`}</div><h3>${esc(t('blocked'))}</h3><div class="dialog-list">${c.blocked.map(o=>`<div class="option-row"><span>${esc(o)}</span>${btn(esc(t('reconnect')),`data-reconnect="${esc(o)}"`,'small-btn')}</div>`).join('')||`<p class="empty">—</p>`}</div><label class="field"><span class="label">${esc(t('originals'))}</span><input id="character-original" list="original-options"><datalist id="original-options">${unique([...state.works.flatMap(w=>w.originals),...(draft?.originals||[])]).map(v=>`<option value="${esc(v)}">`).join('')}</datalist></label><div class="dialog-actions">${btn(esc(t('add')),'id="connect-original"','primary')}</div>`,()=>rerender());
 $$('[data-disconnect]').forEach(b=>b.onclick=()=>{disconnect(c,b.dataset.disconnect);store();characterDialog(id);});
 $$('[data-reconnect]').forEach(b=>b.onclick=()=>{reconnect(c,b.dataset.reconnect);store();characterDialog(id);});
 $('#connect-original').onclick=()=>{const value=$('#character-original').value.trim();if(value){reconnect(c,value);store();characterDialog(id);}};
}
function prioritiesDialog(){modal(t('policy'),`<p class="dialog-tip">${esc(t('priorityHint'))}</p>${Object.entries(state.priorities).map(([site,p])=>`<label class="policy-row"><span>${esc(site)}</span><input type="number" min="1" max="99" step="1" value="${p}" data-priority="${site}" aria-label="${esc(site+' '+t('priority'))}"></label>`).join('')}<p class="dialog-tip">${esc(t('datePriorityHint'))}</p><div class="dialog-actions">${btn(esc(t('apply')==='apply'?(language==='ja'?'適用':'Apply'):t('apply')),'id="apply-priority"','primary')}</div>`);$('#apply-priority').onclick=()=>{const values=$$('[data-priority]');if(values.some(e=>!Number.isInteger(Number(e.value))||Number(e.value)<1||Number(e.value)>99)){values.find(e=>!e.checkValidity())?.reportValidity();return;}for(const e of values)state.priorities[e.dataset.priority]=Number(e.value);store();$('#dialog').close();rerender();};}
function libraryDialog(){modal(t('library'),`<p class="dialog-tip">${esc(t('samplePickerHint'))}</p>${state.works.map(w=>`<button type="button" class="option-row" data-open-work="${w.id}"><span>${esc(w.title)}<small>${esc([w.format,w.creation].filter(Boolean).map(t).join(' · '))}</small></span>${icon('chevron')}</button>`).join('')}<div class="dialog-actions">${btn(icon('plus')+esc(t('new')),'id="library-new"')}</div>`);$$('[data-open-work]').forEach(b=>b.onclick=()=>{$('#dialog').close();go('#/work/'+b.dataset.openWork);});$('#library-new').onclick=()=>{$('#dialog').close();requestLeave(newWork);};}
function bindMetadataSearch(){$$('[data-meta]').forEach(b=>b.onclick=()=>{const k=b.dataset.meta,n=b.dataset.name,works=state.works.filter(w=>(k==='characters'?w.characters.map(id=>state.characters.find(c=>c.id===id)?.name):w[k]).some(v=>(v.name||v)===n));modal(n,`${works.map(w=>`<button class="option-row" type="button" data-result="${w.id}"><span>${esc(w.title)}</span>${icon('chevron')}</button>`).join('')}${k==='characters'?`<div class="dialog-actions">${btn(esc(t('characterSettings')),'id="metadata-character"')}</div>`:''}`);$$('[data-result]').forEach(el=>el.onclick=()=>{$('#dialog').close();go('#/work/'+el.dataset.result);});if(k==='characters')$('#metadata-character').onclick=()=>characterDialog(state.characters.find(c=>c.name===n)?.id);});}
function newWork(){draft=blankWork();baseline=JSON.stringify(draft);currentId=draft.id;mode='edit';lastHash='#/edit/'+draft.id;history.pushState(null,'',lastHash);render();window.scrollTo(0,0);}
function render(){if(mode==='edit'&&draft)editorPage();else{const w=state.works.find(w=>w.id===currentId);if(w)detailPage(w);else shell(`<div class="panel"><h1>${esc(t('notFound'))}</h1><div class="savebar">${btn(esc(t('new')),'data-new','primary')}</div></div>`);}restoreOpen();imageErrors();updateKeyboardState();}
$('#app').addEventListener('toggle',e=>{const el=e.target;if(el.matches?.('[data-open-key]')){el.open?openDetails.add(el.dataset.openKey):openDetails.delete(el.dataset.openKey);try{localStorage.setItem(STORAGE_KEY+'.open',JSON.stringify([...openDetails]));}catch{}}},true);
window.addEventListener('storage',e=>{if(e.key!==STORAGE_KEY||dirty())return;try{const next=JSON.parse(e.newValue||'null');if(next?.version!==1||!Array.isArray(next.works))return;state=next;if(mode==='edit'){const w=state.works.find(w=>w.id===currentId);if(w){draft=clone(w);baseline=JSON.stringify(draft);}}rerender();}catch{}});
// VisualViewport shrinks with a software keyboard. Keep the fixed bar out of that space.
let keyboardBaseline={width:window.innerWidth,height:window.innerHeight};
function updateKeyboardState(){
 const viewport=window.visualViewport,focused=document.activeElement?.matches('input:not([type=radio]):not([type=checkbox]),textarea,[contenteditable=true]');
 if(Math.abs(window.innerWidth-keyboardBaseline.width)>80)keyboardBaseline={width:window.innerWidth,height:window.innerHeight};
 if(!focused)keyboardBaseline.height=Math.max(keyboardBaseline.height,window.innerHeight,viewport?.height||0);
 const hidden=isKeyboardOpen({editing:mode==='edit',mobile:window.matchMedia('(pointer: coarse), (max-width: 760px)').matches,focused,baselineHeight:Math.max(keyboardBaseline.height,window.innerHeight),viewportHeight:viewport?.height||window.innerHeight,scale:viewport?.scale||1});
 document.body.classList.toggle('keyboard-open',hidden);
}
window.visualViewport?.addEventListener('resize',updateKeyboardState);
window.addEventListener('resize',updateKeyboardState);
document.addEventListener('focusin',updateKeyboardState);
document.addEventListener('focusout',()=>setTimeout(updateKeyboardState,0));
window.addEventListener('hashchange',route);
window.addEventListener('beforeunload',e=>{if(dirty()){e.preventDefault();e.returnValue='';}});
route();
